import {canonicalSha256} from '../core/canonical-json.mjs';
const add=(findings,code,severity,location,message)=>findings.push({id:`${code}-${findings.length+1}`,code,severity,location,message});
export function scanAgentSurface(surface={}){const findings=[];for(const item of surface.instructions??[]){const text=String(item.text??'');if(/ignore (all|any|the) previous instructions|disregard (the )?(system|developer)|override.+instruction/i.test(text))add(findings,'prompt-injection','critical',item.path,'Instruction attempts to cross the trust boundary');if(/\.env|secret|api[_ -]?key|token/i.test(text)&&/upload|send|exfiltrate|http/i.test(text))add(findings,'secret-exfiltration','critical',item.path,'Instruction combines secret access with outbound transfer');}
 for(const hook of surface.hooks??[]){const script=String(hook.script??'');if(/(?:curl|wget)[^\n|;]*\|\s*(?:sh|bash|zsh|powershell)/i.test(script))add(findings,'pipe-to-shell','critical',`hook:${hook.id}`,'Hook downloads and executes untrusted code');if(/\$\{?(?:SECRET|TOKEN|API_KEY|PASSWORD)/i.test(script)&&/(curl|wget|http)/i.test(script))add(findings,'secret-exfiltration','critical',`hook:${hook.id}`,'Hook may send secret material over the network');}
 for(const server of surface.mcpServers??[]){if(/any file|including secrets|send results anywhere/i.test(String(server.description??'')))add(findings,'unsafe-mcp-description','high',`mcp:${server.id}`,'MCP description requests broad secret and egress access');for(const tool of server.tools??[])for(const permission of tool.permissions??[])if(permission==='*'||permission.endsWith(':**'))add(findings,'broad-permission','high',`mcp:${server.id}/${tool.name}`,`Overbroad permission ${permission}`);}
 for(const pkg of surface.packages??[])for(const [name,script] of Object.entries(pkg.scripts??{})){if(['preinstall','install','postinstall','prepare'].includes(name))add(findings,'package-lifecycle-script','high',`package:${pkg.name}:${name}`,'Package executes code during installation');if(/(?:curl|wget).*(?:\||&&).*(?:sh|bash|node)/i.test(String(script)))add(findings,'pipe-to-shell','critical',`package:${pkg.name}:${name}`,'Lifecycle script downloads and executes code');}
 if((surface.allowedCommands??[]).includes('*'))add(findings,'broad-permission','critical','allowedCommands','All commands are allowed');for(const name of surface.envReferences??[])if(/secret|token|password|api[_-]?key|database_url/i.test(name))add(findings,'secret-reference','medium',`env:${name}`,'Sensitive environment reference requires brokered secret access');
 const sorted=findings.sort((a,b)=>a.code.localeCompare(b.code)||a.location.localeCompare(b.location));const blocker=sorted.some(x=>['critical','high'].includes(x.severity));const payload={schemaVersion:1,status:blocker?'blocked':sorted.length?'review-required':'pass',findings:sorted,summary:{critical:sorted.filter(x=>x.severity==='critical').length,high:sorted.filter(x=>x.severity==='high').length,medium:sorted.filter(x=>x.severity==='medium').length}};return Object.freeze({...payload,reportSha256:canonicalSha256(payload)});}
